    /**
     * Turns a cart into a VALIDATED order. Blacklist and country checks were already done by the controller;
     * FraudCheckAspect may switch the result to PENDING_REVIEW afterwards.
     */
    public Order checkout(Cart cart, CheckoutRequest req, CustomerSnapshot customer, BigDecimal countrySurcharge) {
        LocalDateTime now = LocalDateTime.now();

        String shippingMethod = req.shippingMethod() == null ? "" : req.shippingMethod().trim().toUpperCase();
        ShippingStrategy strategy = shippingStrategies.get(shippingMethod);
        if (strategy == null) {
            throw new IllegalStateException("unknown shipping method: " + req.shippingMethod());
        }
        if (FeatureFlags.USE_NEW_SHIPPING) {
            // new carrier grid, waiting for the contract to be signed
            strategy = new ExpressShipping();
        }

        if (cart.getLines().isEmpty()) {
            throw new IllegalStateException("the cart is empty");
        }

        // 1. product data, activity and stock
        List<LineDraft> drafts = new ArrayList<>();
        List<Map<String, Object>> reserveItems = new ArrayList<>();
        for (CartLine cl : cart.getLines()) {
            Map<String, Object> raw = catalog.getProduct(cl.getSku());
            if (raw == null) {
                throw new IllegalStateException("unknown product: " + cl.getSku());
            }
            ProductSnapshot p = ProductSnapshot.from(raw);
            if (!p.isActive()) {
                throw new IllegalStateException("product is no longer sold: " + cl.getSku());
            }
            if (p.availableQuantity() < cl.getQuantity()) {
                throw new StockUnavailableException("insufficient stock for " + cl.getSku());
            }
            productCache.remember(raw);
            drafts.add(new LineDraft(p.getSku(), p.getCategory(), cl.getQuantity(), p.getBasePrice(), p.getSalePrice()));
            Map<String, Object> item = new LinkedHashMap<>();
            item.put("sku", cl.getSku());
            item.put("qty", cl.getQuantity());
            reserveItems.add(item);
        }

        // 2. heavy article surcharge, weight comes from the product cache
        boolean heavy = containsHeavyArticle(cart);

        // 3. prices: tier and volume steps, then promo, then totals (the 30% cap is applied by an aspect on close)
        PricingResult priced = calculator.calculate(drafts, customer.getTier());
        String promoCode = null;
        Map<String, Object> promo = null;
        BigDecimal eligibleSubtotal = null;
        if (req.promoCode() != null && !req.promoCode().isBlank()) {
            promoCode = req.promoCode().trim().toUpperCase();
            RemoteResult v = catalog.validatePromo(promoCode, customer.getId(), false, null);
            if (!v.isOk()) {
                throw new RemoteServiceException("catalog-service could not validate the promo code: " + v.getMessage(), null);
            }
            if (!Boolean.TRUE.equals(v.getBody().get("valid"))) {
                throw new IllegalStateException("promo code refused: " + v.getBody().get("reason"));
            }
            promo = v.getBody();
            eligibleSubtotal = applyPromo(priced, promo);
        }
        priced = calculator.close(priced);

        // 4. shipping
        BigDecimal goodsTtc = priced.getGoodsTtc();
        BigDecimal shipping = strategy.baseFee(goodsTtc, customer.getTier());
        if (heavy) {
            shipping = shipping.add(HEAVY_SURCHARGE);
        }
        shipping = shipping.add(countrySurcharge);
        BigDecimal total = goodsTtc.add(shipping);

        // 5. the order itself
        Order order = new Order();
        order.setReference("ORD-" + UUID.randomUUID().toString().replace("-", "").substring(0, 12).toUpperCase());
        order.setCustomerId(customer.getId());
        order.setStatus("VALIDATED");
        order.setB2b(customer.isB2b());
        order.setTierAtCheckout(customer.getTier());
        order.setShippingMethod(shippingMethod);
        order.setShippingCountry(customer.getDefaultCountry());
        order.setGoodsHt(priced.getGoodsHt());
        order.setGoodsTtc(goodsTtc);
        order.setShippingTtc(shipping);
        order.setTotalTtc(total);
        order.setDiscountCapApplied(priced.isCapApplied());
        order.setPromoCode(promoCode);
        order.setRedeemedPoints(0);
        order.setEarnedPoints(0);
        order.setCreatedAt(now);
        order.setExpiresAt(now.plusMinutes(ttlMinutes));
        for (LineDraft d : priced.getLines()) {
            OrderLine line = new OrderLine();
            line.setSku(d.getSku());
            line.setCategory(d.getCategory());
            line.setQuantity(d.getQuantity());
            line.setUnitBasePrice(d.getUnitBase());
            line.setDiscountTier(d.getDiscountTier());
            line.setDiscountVolume(d.getDiscountVolume());
            line.setDiscountPromo(d.getDiscountPromo());
            line.setLineHt(d.getLineHt());
            line.setVatRate(d.getVatRate());
            line.setLineTtc(d.getLineTtc());
            line.setOnSale(d.isOnSale());
            order.addLine(line);
        }
        order.validate();

        // 6. stock reservation, then promo usage (last remote call, so a refusal here only needs the release)
        RemoteResult reservation = catalog.reserve(order.getReference(), reserveItems, ttlMinutes);
        if (!reservation.isOk()) {
            if (reservation.getHttpStatus() == 409) {
                throw new StockUnavailableException(reservation.getMessage());
            }
            throw new IllegalStateException("stock reservation failed: " + reservation.getMessage());
        }
        if (promo != null) {
            RemoteResult consumed;
            try {
                consumed = catalog.validatePromo(promoCode, customer.getId(), true, eligibleSubtotal);
            } catch (RuntimeException e) {
                catalog.release(order.getReference());
                throw e;
            }
            if (!consumed.isOk() || !Boolean.TRUE.equals(consumed.getBody().get("valid"))) {
                catalog.release(order.getReference());
                throw new IllegalStateException("promo code refused: "
                        + (consumed.isOk() ? consumed.getBody().get("reason") : consumed.getMessage()));
            }
        }

        // 7. persist, close the cart
        Order saved = orders.save(order);
        cart.setStatus(Cart.CLOSED);
        cart.getLines().clear();
        carts.save(cart);
        log.info("order created: {}", describe(saved));
        return saved;
    }

    /**
     * Spreads the promo discount over the eligible lines (not on sale, allowed category) and returns the eligible
     * subtotal, which catalog-service needs for the minimum order amount.
     */
    private BigDecimal applyPromo(PricingResult priced, Map<String, Object> promo) {
        String type = String.valueOf(promo.get("type"));
        BigDecimal value = new BigDecimal(String.valueOf(promo.get("value")));
        List<?> allowedRaw = (List<?>) promo.get("allowedCategories");

        List<LineDraft> eligible = new ArrayList<>();
        BigDecimal subtotal = BigDecimal.ZERO.setScale(2);
        for (LineDraft l : priced.getLines()) {
            if (l.isOnSale()) {
                continue;
            }
            if (allowedRaw != null && !allowedRaw.isEmpty() && !allowedRaw.contains(l.getCategory())) {
                continue;
            }
            eligible.add(l);
            subtotal = subtotal.add(l.afterVolume());
        }
        if (eligible.isEmpty()) {
            throw new IllegalStateException("promo code does not apply to any item of the cart");
        }

        if ("PERCENT".equals(type)) {
            for (LineDraft l : eligible) {
                BigDecimal d = l.afterVolume().multiply(value).divide(HUNDRED, 2, RoundingMode.HALF_UP);
                l.setDiscountPromo(d);
            }
        } else if ("FIXED".equals(type)) {
            BigDecimal fixed = value.min(subtotal).setScale(2, RoundingMode.HALF_UP);
            BigDecimal remaining = fixed;
            for (int i = 0; i < eligible.size(); i++) {
                LineDraft l = eligible.get(i);
                BigDecimal share;
                if (i == eligible.size() - 1) {
                    // the last line absorbs the rounding difference
                    share = remaining.min(l.afterVolume());
                } else {
                    share = fixed.multiply(l.afterVolume()).divide(subtotal, 2, RoundingMode.HALF_UP).min(l.afterVolume());
                }
                l.setDiscountPromo(share);
                remaining = remaining.subtract(share);
            }
        } else {
            throw new IllegalStateException("unsupported promo type: " + type);
        }
        return subtotal;
    }

