    /** Null when the order does not exist. */
    public Order pay(Long orderId, PayRequest req) {
        Order order = orders.findById(orderId).orElse(null);
        if (order == null) {
            return null;
        }
        if (!"VALIDATED".equals(order.getStatus())) {
            throw new IllegalStateException("order cannot be paid in status " + order.getStatus());
        }
        if (LocalDateTime.now().isAfter(order.getExpiresAt())) {
            markExpired(order);
            throw new IllegalStateException("the stock reservation expired, the order is now EXPIRED");
        }

        CustomerSnapshot customer = loadCustomer(order.getCustomerId());

        PaymentOutcome outcome = paymentService.process(order, customer, req);
        if (!outcome.isOk()) {
            throw new PaymentRefusedException(outcome.getMessage());
        }

        RemoteResult stock = catalog.confirm(order.getReference());
        if (!stock.isOk()) {
            paymentService.rollback(order, outcome);
            if (stock.getHttpStatus() == 409) {
                markExpired(order);
                throw new IllegalStateException("the stock reservation expired, the order is now EXPIRED");
            }
            throw new IllegalStateException("stock confirmation failed: " + stock.getMessage());
        }

        order.setStatus("PAID");
        order.setPaidAt(LocalDateTime.now());
        order.setPaymentMethod(outcome.getMethod());
        order.setRedeemedPoints(outcome.getRedeemedPoints());
        order.setPaidAmount(outcome.getAmountDue());
        // LoyaltyListener fills earnedPoints
        events.publishEvent(new OrderPaidEvent(order));
        return orders.save(order);
    }

    // ------------------------------------------------------------------------------------------------
    // LIFECYCLE
    // ------------------------------------------------------------------------------------------------

    /** APPROVE / REJECT / SHIP / DELIVER. Null when the order does not exist. */
    public Order changeStatus(Long orderId, String action) {
        Order order = orders.findById(orderId).orElse(null);
        if (order == null) {
            return null;
        }
        String a = action == null ? "" : action.trim().toUpperCase();
        String status = order.getStatus();

        if (a.equals("APPROVE")) {
            if (!status.equals("PENDING_REVIEW")) {
                throw new IllegalStateException("only a PENDING_REVIEW order can be approved (current status: " + status + ")");
            }
            if (LocalDateTime.now().isAfter(order.getExpiresAt())) {
                markExpired(order);
                throw new IllegalStateException("the stock reservation expired, the order is now EXPIRED");
            }
            // re-reserving an existing reference extends the hold
            RemoteResult r = catalog.reserve(order.getReference(), null, ttlMinutes);
            if (!r.isOk()) {
                markExpired(order);
                throw new IllegalStateException("the stock reservation expired, the order is now EXPIRED");
            }
            order.setStatus("VALIDATED");
            order.setExpiresAt(LocalDateTime.now().plusMinutes(ttlMinutes));
        } else if (a.equals("REJECT")) {
            if (!status.equals("PENDING_REVIEW")) {
                throw new IllegalStateException("only a PENDING_REVIEW order can be rejected (current status: " + status + ")");
            }
            order.setStatus("REJECTED");
            try {
                RemoteResult r = catalog.release(order.getReference());
                if (!r.isOk()) {
                    log.warn("stock release refused for {}: {}", order.getReference(), r.getMessage());
                }
            } catch (RemoteServiceException e) {
                log.warn("stock release failed for {}: {}", order.getReference(), e.getMessage());
            }
        } else if (a.equals("SHIP")) {
            order.ship();
        } else if (a.equals("DELIVER")) {
            order.deliver();
        } else {
            throw new IllegalStateException("unknown action: " + action);
        }
        return orders.save(order);
    }

    /** Used by the expiry job and by the pay / approve paths. */
    public void markExpired(Order order) {
        order.setStatus("EXPIRED");
        orders.save(order);
        try {
            catalog.release(order.getReference());
        } catch (RemoteServiceException e) {
            log.warn("stock release failed for expired order {}: {}", order.getReference(), e.getMessage());
        }
    }

    // ------------------------------------------------------------------------------------------------
    // CANCELLATION
    // ------------------------------------------------------------------------------------------------

    /**
     * Cancels an order. The status is saved first, then the remote side effects run one after the other without any
     * compensation: a failing step is reported in "warnings" and the following steps still run.
     */
    public Map<String, Object> cancel(Long orderId) {
        Order order = orders.findById(orderId).orElse(null);
        if (order == null) {
            return null;
        }
        String status = order.getStatus();
        List<String> warnings = new ArrayList<>();
        Map<String, Object> result = new LinkedHashMap<>();
        BigDecimal refund = BigDecimal.ZERO.setScale(2);
        int restituted = 0;
        int reclaimed = 0;

        if (status.equals("SHIPPED") || status.equals("DELIVERED") || status.equals("RETURNED")) {
            throw new IllegalStateException("an order cannot be cancelled once shipped (current status: " + status + ")");
        }
        if (status.equals("CANCELLED") || status.equals("REJECTED") || status.equals("EXPIRED")) {
            throw new IllegalStateException("order is already " + status);
        }

        if (status.equals("VALIDATED") || status.equals("PENDING_REVIEW")) {
            order.setStatus("CANCELLED");
            orders.save(order);
            run(warnings, "stock release", () -> catalog.release(order.getReference()));
        } else if (status.equals("PAID")) {
            order.setStatus("CANCELLED");
            refund = order.getPaidAmount();
            order.setRefundedAmount(refund);
            orders.save(order);

            // 1. points spent on the order go back to the customer
            if (order.getRedeemedPoints() > 0) {
                restituted = order.getRedeemedPoints();
                final int pts = restituted;
                run(warnings, "points restitution",
                        () -> customers.redeem(order.getCustomerId(), -pts, null, order.getReference()));
            }
            // 2. points earned on the order are taken back
            if (order.getEarnedPoints() > 0) {
                reclaimed = order.getEarnedPoints();
                final int pts = reclaimed;
                run(warnings, "earned points clawback",
                        () -> customers.earn(order.getCustomerId(), -pts, order.getReference()));
            }
            // 3. business credit is released
            if ("B2B_CREDIT".equals(order.getPaymentMethod())) {
                final BigDecimal amount = order.getPaidAmount();
                run(warnings, "credit release", () -> customers.consumeCredit(order.getCustomerId(), amount.negate()));
            }
            // 4. stock goes back to the shelves
            List<Map<String, Object>> items = new ArrayList<>();
            for (OrderLine l : order.getLines()) {
                Map<String, Object> item = new LinkedHashMap<>();
                item.put("sku", l.getSku());
                item.put("qty", l.getQuantity());
                items.add(item);
            }
            run(warnings, "restock", () -> catalog.restock(order.getReference(), items));
        } else {
            throw new IllegalStateException("order cannot be cancelled in status " + status);
        }

        result.put("order", order);
        result.put("refundedAmount", refund);
        result.put("pointsRestituted", restituted);
        result.put("pointsReclaimed", reclaimed);
        result.put("warnings", warnings);
        return result;
    }

    private void run(List<String> warnings, String step, Supplier<RemoteResult> call) {
        try {
            RemoteResult r = call.get();
            if (!r.isOk()) {
                warnings.add(step + " refused: " + r.getMessage());
            }
        } catch (RemoteServiceException e) {
            warnings.add(step + " failed: " + e.getMessage());
        }
    }

    // ------------------------------------------------------------------------------------------------
    // RETURNS
    // ------------------------------------------------------------------------------------------------

    /**
     * Records a (validated) partial or total return. Same remote-effects policy as cancel().
     * items: sku -> quantity, already checked by ReturnService.
     */
    public Map<String, Object> processReturn(Order order, Map<String, Integer> items) {
        List<String> warnings = new ArrayList<>();
        BigDecimal returnedHt = BigDecimal.ZERO.setScale(2);
        BigDecimal returnedTtc = BigDecimal.ZERO.setScale(2);
        List<Map<String, Object>> restockItems = new ArrayList<>();
        StringBuilder description = new StringBuilder();

        for (Map.Entry<String, Integer> e : items.entrySet()) {
            OrderLine line = order.findLine(e.getKey());
            int qty = e.getValue();
            // amounts first: they depend on the quantity already returned
            returnedHt = returnedHt.add(line.returnAmountHt(qty));
            returnedTtc = returnedTtc.add(line.returnAmountTtc(qty));
            line.setReturnedQuantity(line.getReturnedQuantity() + qty);

            Map<String, Object> item = new LinkedHashMap<>();
            item.put("sku", e.getKey());
            item.put("qty", qty);
            restockItems.add(item);
            if (description.length() > 0) {
                description.append(',');
            }
            description.append(e.getKey()).append(':').append(qty);
        }

        // ratio = returnedTtc / goodsTtc, applied with a floor on the points
        int restituted = BigDecimal.valueOf(order.getRedeemedPoints()).multiply(returnedTtc)
                .divide(order.getGoodsTtc(), 0, RoundingMode.DOWN).intValue();
        int reclaimed = BigDecimal.valueOf(order.getEarnedPoints()).multiply(returnedTtc)
                .divide(order.getGoodsTtc(), 0, RoundingMode.DOWN).intValue();
        BigDecimal refund = returnedTtc.subtract(POINT_VALUE.multiply(BigDecimal.valueOf(restituted)));

        BigDecimal alreadyRefunded = order.getRefundedAmount() == null ? BigDecimal.ZERO : order.getRefundedAmount();
        order.setRefundedAmount(alreadyRefunded.add(refund));
        boolean everythingReturned = true;
        for (OrderLine l : order.getLines()) {
            if (l.getReturnedQuantity() < l.getQuantity()) {
                everythingReturned = false;
            }
        }
        if (everythingReturned) {
            order.setStatus("RETURNED");
        }
        orders.save(order);

        ReturnRecord record = new ReturnRecord();
        record.setOrderId(order.getId());
        record.setCustomerId(order.getCustomerId());
        record.setGoodsHt(returnedHt);
        record.setGoodsTtc(returnedTtc);
        record.setRefundAmount(refund);
        record.setPointsRestituted(restituted);
        record.setPointsReclaimed(reclaimed);
        record.setItems(description.toString());
        record.setCreatedAt(LocalDateTime.now());
        record = returnRecords.save(record);

        final int pointsBack = restituted;
        final int pointsTaken = reclaimed;
        final BigDecimal refundAmount = refund;
        if (pointsBack > 0) {
            run(warnings, "points restitution",
                    () -> customers.redeem(order.getCustomerId(), -pointsBack, null, order.getReference()));
        }
        if (pointsTaken > 0) {
            run(warnings, "earned points clawback",
                    () -> customers.earn(order.getCustomerId(), -pointsTaken, order.getReference()));
        }
        if ("B2B_CREDIT".equals(order.getPaymentMethod()) && refund.signum() > 0) {
            run(warnings, "credit release",
                    () -> customers.consumeCredit(order.getCustomerId(), refundAmount.negate()));
        }
        run(warnings, "restock", () -> catalog.restock(order.getReference(), restockItems));

        Map<String, Object> result = new LinkedHashMap<>();
        result.put("returnId", record.getId());
        result.put("orderStatus", order.getStatus());
        result.put("returnedGoodsHt", returnedHt);
        result.put("returnedGoodsTtc", returnedTtc);
        result.put("refundAmount", refund);
        result.put("pointsRestituted", restituted);
        result.put("pointsReclaimed", reclaimed);
        result.put("warnings", warnings);
        return result;
    }

    // ------------------------------------------------------------------------------------------------
    // HELPERS (some of them exist twice, nobody dared to merge them)
    // ------------------------------------------------------------------------------------------------

    private CustomerSnapshot loadCustomer(Long customerId) {
        RemoteResult cr = customers.getCustomer(customerId);
        if (!cr.isOk()) {
            throw new IllegalStateException("customer lookup failed: " + cr.getMessage());
        }
        return CustomerSnapshot.from(cr.getBody());
    }

    /** Any article above 30 kg triggers the flat surcharge, whatever the customer tier. */
    private boolean containsHeavyArticle(Cart cart) {
        boolean heavy = false;
        for (CartLine cl : cart.getLines()) {
            ProductCache pc = productCache.find(cl.getSku());
            if (pc == null) {
                continue;
            }
            if (pc.getWeightKg().compareTo(HEAVY_WEIGHT_KG) > 0) {
                heavy = true;
            }
        }
        return heavy;
    }

    private BigDecimal money(BigDecimal v) {
        if (v == null) {
            return BigDecimal.ZERO.setScale(2);
        }
        return v.setScale(2, RoundingMode.HALF_UP);
    }

    private BigDecimal nz(BigDecimal v) {
        return v == null ? BigDecimal.ZERO : v;
    }

    private String describe(Order order) {
        StringBuilder sb = new StringBuilder();
        sb.append(order.getReference()).append(" customer=").append(order.getCustomerId());
        sb.append(" status=").append(order.getStatus());
        sb.append(" lines=").append(order.getLines().size());
        sb.append(" total=").append(money(order.getTotalTtc()));
        return sb.toString();
    }

    private boolean isFinished(Order order) {
        String s = order.getStatus();
        if (s.equals("CANCELLED")) {
            return true;
        } else if (s.equals("REJECTED")) {
            return true;
        } else if (s.equals("EXPIRED")) {
            return true;
        } else if (s.equals("RETURNED")) {
            return true;
        }
        return false;
    }

    private boolean isFinishedAgain(String s) {
        return "CANCELLED".equals(s) || "REJECTED".equals(s) || "EXPIRED".equals(s) || "RETURNED".equals(s);
    }

    /** Customer-facing recap used in logs and in support exports. */
    public Map<String, Object> summarize(Order order) {
        Map<String, Object> m = new LinkedHashMap<>();
        m.put("reference", order.getReference());
        m.put("status", order.getStatus());
        m.put("finished", isFinished(order));
        BigDecimal paid = nz(order.getPaidAmount());
        BigDecimal refunded = nz(order.getRefundedAmount());
        m.put("paid", money(paid));
        m.put("refunded", money(refunded));
        m.put("net", money(paid.subtract(refunded)));
        int units = 0;
        int returned = 0;
        for (OrderLine l : order.getLines()) {
            units += l.getQuantity();
            returned += l.getReturnedQuantity();
        }
        m.put("units", units);
        m.put("returnedUnits", returned);
        if (order.getRedeemedPoints() > 0) {
            m.put("pointsValue", money(POINT_VALUE.multiply(BigDecimal.valueOf(order.getRedeemedPoints()))));
        }
        return m;
    }

