    /**
     * First version of the checkout (before stock reservations existed): prices come from the cart, nothing is reserved,
     * stock is decremented right away. DO NOT REMOVE - the mobile app v1 may still call it.
     */
    public Order checkoutLegacyV1(Cart cart, String shippingMethod) {
        if (!legacyPricingV1) {
            return null;
        }
        Order order = new Order();
        order.setReference("LEG-" + System.currentTimeMillis());
        order.setCustomerId(cart.getCustomerId());
        order.setStatus("VALIDATED");
        order.setCreatedAt(LocalDateTime.now());
        order.setShippingMethod(shippingMethod);
        order.setShippingCountry("FR");
        order.setTierAtCheckout("STANDARD");
        BigDecimal ht = BigDecimal.ZERO;
        BigDecimal ttc = BigDecimal.ZERO;
        for (CartLine cl : cart.getLines()) {
            Map<String, Object> raw = catalog.getProduct(cl.getSku());
            if (raw == null) {
                continue;
            }
            ProductSnapshot p = ProductSnapshot.from(raw);
            BigDecimal unit = p.getBasePrice();
            if (p.getSalePrice() != null) {
                unit = p.getSalePrice();
            }
            BigDecimal lineHt = unit.multiply(BigDecimal.valueOf(cl.getQuantity()));
            if (cl.getQuantity() >= 10) {
                lineHt = lineHt.multiply(new BigDecimal("0.90"));
            } else if (cl.getQuantity() >= 5) {
                lineHt = lineHt.multiply(new BigDecimal("0.95"));
            }
            BigDecimal rate = new BigDecimal("0.20");
            if (p.getCategory().equals("FOOD")) {
                rate = new BigDecimal("0.07");
            } else if (p.getCategory().equals("BOOKS")) {
                rate = new BigDecimal("0.07");
            }
            BigDecimal lineTtc = lineHt.multiply(BigDecimal.ONE.add(rate));
            OrderLine line = new OrderLine();
            line.setSku(p.getSku());
            line.setCategory(p.getCategory());
            line.setQuantity(cl.getQuantity());
            line.setUnitBasePrice(p.getBasePrice());
            line.setLineHt(money(lineHt));
            line.setVatRate(rate);
            line.setLineTtc(money(lineTtc));
            line.setOnSale(p.getSalePrice() != null);
            order.addLine(line);
            ht = ht.add(lineHt);
            ttc = ttc.add(lineTtc);
        }
        order.setGoodsHt(money(ht));
        order.setGoodsTtc(money(ttc));
        BigDecimal shipping = new BigDecimal("4.90");
        if (shippingMethod != null && shippingMethod.equals("EXPRESS")) {
            shipping = new BigDecimal("9.90");
        }
        // free shipping above 40 EUR
        if (ttc.compareTo(new BigDecimal("40")) >= 0 && !"EXPRESS".equals(shippingMethod)) {
            shipping = BigDecimal.ZERO;
        }
        order.setShippingTtc(money(shipping));
        order.setTotalTtc(money(ttc.add(shipping)));
        order.setLegacyRef("V1");
        order.setMigrationFlag(Boolean.TRUE);
        return orders.save(order);
    }

    /** Old cancellation: refunded in cash only, no points, no credit, no restock call. */
    public Order cancelLegacy(Long orderId) {
        if (!legacyPricingV1) {
            return null;
        }
        Order order = orders.findById(orderId).orElse(null);
        if (order == null) {
            return null;
        }
        if (order.getStatus().equals("SHIPPED")) {
            return order;
        } else if (order.getStatus().equals("DELIVERED")) {
            return order;
        } else if (order.getStatus().equals("CANCELLED")) {
            return order;
        }
        if (order.getStatus().equals("PAID")) {
            order.setRefundedAmount(order.getTotalTtc());
        } else if (order.getStatus().equals("VALIDATED")) {
            order.setRefundedAmount(BigDecimal.ZERO);
        } else {
            order.setRefundedAmount(BigDecimal.ZERO);
        }
        order.setStatus("CANCELLED");
        return orders.save(order);
    }

    /** Old return handling: whole order only, 30 days, refund of the shipping fee included. */
    public Order returnLegacy(Long orderId) {
        if (!legacyPricingV1) {
            return null;
        }
        Order order = orders.findById(orderId).orElse(null);
        if (order == null || !"DELIVERED".equals(order.getStatus())) {
            return null;
        }
        if (order.getDeliveredAt().plusDays(30).isBefore(LocalDateTime.now())) {
            return null;
        }
        for (OrderLine l : order.getLines()) {
            l.setReturnedQuantity(l.getQuantity());
        }
        order.setRefundedAmount(order.getTotalTtc());
        order.setStatus("RETURNED");
        return orders.save(order);
    }

