    // never scheduled, the 2019 migration was done by hand
    public int migrateOldStatuses() {
        int changed = 0;
        for (Order o : orders.findAll()) {
            if ("CLOSED".equals(o.getStatus())) {
                o.setStatus("DELIVERED");
                o.setMigrationFlag(Boolean.TRUE);
                orders.save(o);
                changed++;
            } else if ("OPEN".equals(o.getStatus())) {
                o.setStatus("VALIDATED");
                o.setMigrationFlag(Boolean.TRUE);
                orders.save(o);
                changed++;
            }
        }
        return changed;
    }

    // FIXME: chargebacks are handled by finance in a spreadsheet, this was the first attempt
    public Map<String, Object> handleChargeback(Long orderId, String reason) {
        Map<String, Object> result = new LinkedHashMap<>();
        if (!legacyPricingV1) {
            result.put("handled", false);
            return result;
        }
        Order order = orders.findById(orderId).orElse(null);
        if (order == null) {
            result.put("handled", false);
            result.put("reason", "unknown order");
            return result;
        }
        if (order.getPaymentMethod() == null) {
            result.put("handled", false);
            result.put("reason", "order was never paid");
            return result;
        }
        if (order.getPaymentMethod().equals("CARD")) {
            order.setRefundedAmount(nz(order.getRefundedAmount()).add(nz(order.getPaidAmount())));
            if (order.getRedeemedPoints() > 0) {
                customers.redeem(order.getCustomerId(), -order.getRedeemedPoints(), null, order.getReference());
            }
            if (order.getEarnedPoints() > 0) {
                customers.earn(order.getCustomerId(), -order.getEarnedPoints(), order.getReference());
            }
        } else if (order.getPaymentMethod().equals("B2B_CREDIT")) {
            customers.consumeCredit(order.getCustomerId(), nz(order.getPaidAmount()).negate());
        } else {
            result.put("handled", false);
            result.put("reason", "unsupported payment method");
            return result;
        }
        order.setLegacyRef("CHARGEBACK:" + reason);
        orders.save(order);
        result.put("handled", true);
        result.put("refunded", money(order.getRefundedAmount()));
        return result;
    }

    // one parcel per 30 kg, abandoned when the carrier changed its grid
    public List<List<OrderLine>> splitOrderByWeight(Order order) {
        List<List<OrderLine>> parcels = new ArrayList<>();
        List<OrderLine> current = new ArrayList<>();
        BigDecimal currentWeight = BigDecimal.ZERO;
        for (OrderLine line : order.getLines()) {
            ProductCache pc = productCache.find(line.getSku());
            BigDecimal unitWeight = pc == null ? BigDecimal.ONE : pc.getWeightKg();
            BigDecimal lineWeight = unitWeight.multiply(BigDecimal.valueOf(line.getQuantity()));
            if (currentWeight.add(lineWeight).compareTo(HEAVY_WEIGHT_KG) > 0 && !current.isEmpty()) {
                parcels.add(current);
                current = new ArrayList<>();
                currentWeight = BigDecimal.ZERO;
            }
            current.add(line);
            currentWeight = currentWeight.add(lineWeight);
        }
        if (!current.isEmpty()) {
            parcels.add(current);
        }
        return parcels;
    }

    // double points weekend, switched off by hand each time
    public int applyLoyaltyCampaign(Order order, int multiplier) {
        if (!legacyPricingV1 || multiplier <= 1) {
            return 0;
        }
        int extra = order.getEarnedPoints() * (multiplier - 1);
        if (extra > 0) {
            RemoteResult r = customers.earn(order.getCustomerId(), extra, order.getReference());
            if (r.isOk()) {
                order.setEarnedPoints(order.getEarnedPoints() + extra);
                orders.save(order);
                return extra;
            }
        }
        return 0;
    }

    // abandoned carts of the same customer were merged before the 2019 cart rewrite
    public Cart mergeOpenCarts(Long customerId) {
        Cart target = null;
        for (Cart c : carts.findAll()) {
            if (!customerId.equals(c.getCustomerId()) || !Cart.OPEN.equals(c.getStatus())) {
                continue;
            }
            if (target == null) {
                target = c;
                continue;
            }
            for (CartLine l : new ArrayList<>(c.getLines())) {
                CartLine existing = target.findLine(l.getSku());
                if (existing == null) {
                    target.getLines().add(new CartLine(target, l.getSku(), l.getQuantity()));
                } else {
                    existing.setQuantity(existing.getQuantity() + l.getQuantity());
                }
            }
            c.getLines().clear();
            c.setStatus(Cart.CLOSED);
            carts.save(c);
        }
        return target == null ? null : carts.save(target);
    }

    // TODO: GDPR export/anonymisation is handled by the DPO tooling now
    public int anonymizeOrders(Long customerId) {
        int count = 0;
        for (Order o : orders.findByCustomerIdOrderByCreatedAtDesc(customerId)) {
            if (isFinishedAgain(o.getStatus()) || "DELIVERED".equals(o.getStatus())) {
                o.setShippingCountry(null);
                o.setLegacyRef("ANON");
                o.setMigrationFlag(Boolean.TRUE);
                orders.save(o);
                count++;
            }
        }
        return count;
    }

    // recomputes earnedPoints with the pre-2020 formula (shipping included)
    public int rebuildEarnedPointsLegacy() {
        int touched = 0;
        if (!legacyPricingV1) {
            return touched;
        }
        for (Order o : orders.findAll()) {
            if (o.getPaidAt() == null) {
                continue;
            }
            BigDecimal paidShare = o.getTotalTtc().subtract(POINT_VALUE.multiply(BigDecimal.valueOf(o.getRedeemedPoints())));
            int points = paidShare.setScale(0, RoundingMode.DOWN).intValue();
            if (points != o.getEarnedPoints()) {
                o.setEarnedPoints(points);
                orders.save(o);
                touched++;
            }
        }
        return touched;
    }

    // not called anywhere since the 2019 pricing rewrite
    public BigDecimal recalculateOrderTotalsLegacy(Order order) {
        if (!legacyPricingV1) {
            return order.getTotalTtc();
        }
        BigDecimal sum = BigDecimal.ZERO;
        for (OrderLine l : order.getLines()) {
            BigDecimal unit = l.getUnitBasePrice();
            if (l.getQuantity() >= 10) {
                unit = unit.multiply(new BigDecimal("0.90"));
            } else if (l.getQuantity() >= 5) {
                unit = unit.multiply(new BigDecimal("0.95"));
            }
            sum = sum.add(unit.multiply(BigDecimal.valueOf(l.getQuantity())));
        }
        // free shipping above 40 EUR
        if (sum.compareTo(new BigDecimal("40")) >= 0) {
            return sum;
        }
        return sum.add(new BigDecimal("4.90"));
    }

    // DO NOT REMOVE - used by batch
    public void applyBlackFridayRules(PricingResult result) {
        for (LineDraft l : result.getLines()) {
            if (!l.isOnSale()) {
                l.setDiscountPromo(l.afterVolume().multiply(new BigDecimal("0.20")));
            }
        }
    }

